/// <summary>
/// 126687 2nd API to communicate during submission / validation / posting of the journal
/// Devloped by TCS
/// </summary>
[DataContractAttribute]
class MET_CheckJournalPostStatusRequest
{
    private str JournalId;
    private str dataAreaId;

}

Method.Source:
    [DataMember("JournalId")]
    public str parmJournalId(str _value = JournalId)
    {
        if (!prmIsDefault(_value))
        {
            JournalId = _value;
        }

        return JournalId;
    }

    [DataMember("DataAreaId")]
    public str parmDataAreaId(str _value = dataAreaId)
    {
        if (!prmIsDefault(_value))
        {
            dataAreaId = _value;
        }

        return dataAreaId;
    }
